package com.vandorlabs.neoforge.propulsion;
import com.google.gson.*;import com.vandorlabs.propulsion.*;import java.nio.file.*;import java.util.*;
/** Direct shared axis-box construction compared with actual released Forge wrapper bytes. */
public final class PropulsionBoxChecks {
 private record Model(JsonArray elements,Map<String,String> textures){}private static final Map<String,Model> MODELS=new HashMap<>();
 private static Model model(String name)throws Exception{var known=MODELS.get(name);if(known!=null)return known;if(name.startsWith("minecraft:"))return new Model(new JsonArray(),Map.of());String[] id=name.split(":",2);JsonObject object;try(var reader=new java.io.InputStreamReader(Objects.requireNonNull(PropulsionBoxChecks.class.getResourceAsStream("/assets/"+id[0]+"/models/"+id[1]+".json")),java.nio.charset.StandardCharsets.UTF_8)){object=JsonParser.parseReader(reader).getAsJsonObject();}var parent=object.has("parent")?model(object.get("parent").getAsString()):new Model(new JsonArray(),Map.of());var textures=new HashMap<>(parent.textures);if(object.has("textures"))for(var entry:object.getAsJsonObject("textures").entrySet())textures.put(entry.getKey(),entry.getValue().getAsString());var result=new Model(object.has("elements")?object.getAsJsonArray("elements"):parent.elements,Map.copyOf(textures));MODELS.put(name,result);return result;}
 private static float[] vector(JsonArray a){float[] v=new float[a.size()];for(int i=0;i<v.length;i++)v[i]=a.get(i).getAsFloat();return v;}private static String texture(Model model,String reference){for(int i=0;i<16&&reference.startsWith("#");i++)reference=model.textures.get(reference.substring(1));if(reference==null||reference.startsWith("#"))throw new AssertionError("Source engine texture reference");return reference;}
 private static String key(String sprite,int direction,int cull,int tint,boolean shade,int[] data){return sprite+"/"+direction+"/"+cull+"/"+tint+"/"+shade+"/"+Arrays.toString(data);}
 public static void main(String[] args)throws Exception{int poses=0,quads=0;try(var lines=Files.lines(Path.of(args[0]))){for(String line:(Iterable<String>)lines::iterator){var r=JsonParser.parseString(line).getAsJsonObject();if(r.get("source").getAsString().endsWith(".obj"))continue;var m=model(r.get("id").getAsString());int x=r.get("x").getAsInt(),y=r.get("y").getAsInt();Map<String,Integer> expected=new HashMap<>();Map<String,JsonArray> extents=new HashMap<>();for(var e:r.getAsJsonArray("quads")){var q=e.getAsJsonObject();int[] data=new int[32];for(int i=0;i<data.length;i++)data[i]=q.getAsJsonArray("data").get(i).getAsInt();expected.merge(key(q.get("sprite").getAsString(),q.get("face").getAsInt(),q.get("cull").getAsInt(),q.get("tint").getAsInt(),q.get("shade").getAsBoolean(),data),1,Integer::sum);extents.put(q.get("sprite").getAsString(),q.getAsJsonArray("extent"));}
  for(var raw:m.elements){var element=raw.getAsJsonObject();if(element.has("rotation"))throw new AssertionError("Unfrozen engine element rotation");for(var entry:element.getAsJsonObject("faces").entrySet()){var f=entry.getValue().getAsJsonObject();String spriteId=texture(m,f.get("texture").getAsString());var extent=extents.get(spriteId);var sprite=new PropulsionObjMesh.Sprite(){public float minU(){return extent.get(0).getAsFloat();}public float maxU(){return extent.get(1).getAsFloat();}public float minV(){return extent.get(2).getAsFloat();}public float maxV(){return extent.get(3).getAsFloat();}public int width(){return 128;}public int height(){return 128;}};int direction=net.minecraft.core.Direction.byName(entry.getKey()).get3DDataValue(),cull=f.has("cullface")?net.minecraft.core.Direction.byName(f.get("cullface").getAsString()).get3DDataValue():-1,tint=f.has("tintindex")?f.get("tintindex").getAsInt():-1;boolean shade=!element.has("shade")||element.get("shade").getAsBoolean();var face=new PropulsionBoxMesh.Face(spriteId,vector(element.getAsJsonArray("from")),vector(element.getAsJsonArray("to")),direction,vector(f.getAsJsonArray("uv")),f.has("rotation")?f.get("rotation").getAsInt():0,cull,tint,shade);int[] data=new int[32];for(int v=0;v<4;v++)data[v*8+3]=-1;int posed=PropulsionBoxMesh.bake(face,x,y,sprite,data);if(cull>=0)throw new AssertionError("Source engine cull policy needs explicit fixture");String key=key(spriteId,posed,cull,tint,shade,data);int count=expected.getOrDefault(key,0);if(count==0)throw new AssertionError("Actual Source direct box "+r.get("id")+"/"+x+"/"+y+"/"+entry.getKey()+" actual="+Arrays.toString(data));if(count==1)expected.remove(key);else expected.put(key,count-1);quads++;}}
  if(!expected.isEmpty())throw new AssertionError("Source box multiplicity");poses++;}}if(poses!=15775||quads!=181164)throw new AssertionError("Source box coverage");System.out.println("Native propulsion box PASS poses="+poses+" quads="+quads+" exactSource JSON vertices/UVinset/normal/order/shade");}
}
